/* @lc app=leetcode id=2271 lang=kotlin */
class Solution { fun maximumWhiteTiles(tiles: Array<IntArray>, carpetLen: Int): Int = tiles.sortedBy { it[0] }.let { t -> LongArray(4).let { v -> t.indices.forEach { i -> run { while (v[0] < t.size && t[v[0].toInt()][1].toLong() - t[i][0] + 1 <= carpetLen) { v[1] = (v[1] + t[v[0].toInt()][1] - t[v[0].toInt()][0] + 1).also { v[0]++ } } }.also { v[2] = maxOf(v[2], v[1] + if (v[0] < t.size) maxOf(0L, t[i][0].toLong() + carpetLen - t[v[0].toInt()][0]) else 0L) }.also { v[1] = v[1] - (t[i][1] - t[i][0] + 1) } }.run { minOf(carpetLen.toLong(), v[2]).toInt() } } } }